import { cookies, headers } from 'next/headers'

export default async function UserPreferences() {
  const cookieStore = await cookies()
  const headerList = await headers()

  const theme = cookieStore.get('theme')?.value ?? 'light'

  const acceptLanguage = headerList.get('accept-language')
  // Accept-Language looks like "en-US,en;q=0.9,fr;q=0.8" — the first entry
  // is the most preferred language.
  const language = acceptLanguage?.split(',')[0]?.trim() || 'unknown'

  return (
    <section>
      <p>
        Current theme: <strong>{theme}</strong>
      </p>
      <p>
        Preferred language: <strong>{language}</strong>
      </p>
    </section>
  )
}

